<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_admin();$id=(int)($_GET['id']??0);$stmt=$pdo->prepare("SELECT t.*,u.name author_name,u.email author_email FROM twibbons t LEFT JOIN users u ON u.id=t.owner_id WHERE t.id=? AND t.visibility='public'");$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){http_response_code(404);$title='Template tidak ditemukan';require __DIR__.'/not-found.php';exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));if($title===''||mb_strlen($title)>120)throw new RuntimeException('Judul wajib diisi dan maksimal 120 karakter.');$file=$item['template_image'];if(($_FILES['template_image']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$newFile=store_image($_FILES['template_image'],__DIR__.'/uploads');$oldPath=__DIR__.'/uploads/'.basename($file);if(is_file($oldPath)&&basename($file)!=='sample_template.png')@unlink($oldPath);$file=$newFile;}$pdo->prepare('UPDATE twibbons SET title=?,description=?,template_image=? WHERE id=?')->execute([$title,$description,$file,$id]);flash('success','Template berhasil diperbarui.');header('Location: /twibbown/admin');exit;}catch(Throwable $e){$error=$e->getMessage();}}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Template — Bingkaiin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">B</span>Bingkaiin</a></div></header><main class="container edit-page"><div class="page-head"><a class="eyebrow" href="admin">← Kembali ke template</a><h1 class="page-title" style="margin-top:14px">Edit template</h1><p class="subtitle">Perbarui informasi tanpa mengubah URL yang sudah dibagikan.</p></div><?php if(!empty($error)):?><div class="alert alert-error"><?=e($error)?></div><?php endif?><div class="edit-layout"><aside class="panel edit-preview"><img src="uploads/<?=e(basename($item['template_image']))?>" alt="<?=e($item['title'])?>"><div class="author-row"><span class="mini-avatar"><?=e(strtoupper(mb_substr($item['author_name']?:'A',0,1)))?></span><div><small>Dibuat oleh</small><strong><?=e($item['author_name']?:'Administrator (data lama)')?></strong><small><?=e($item['author_email']?:'Pembuat tidak tercatat')?></small></div></div></aside><section class="panel"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="field"><label for="title">Judul template</label><input id="title" name="title" value="<?=e($item['title'])?>" required maxlength="120"></div><div class="field"><label for="description">Deskripsi</label><textarea id="description" name="description" rows="5" maxlength="500"><?=e($item['description'])?></textarea></div><div class="field"><label for="template_image">Ganti gambar <small>(opsional)</small></label><input id="template_image" name="template_image" type="file" accept="image/png,image/jpeg,image/webp"><small class="subtitle">Biarkan kosong untuk mempertahankan gambar saat ini.</small></div><div class="button-row"><a class="btn btn-secondary" href="admin">Batal</a><button class="btn btn-primary">Simpan perubahan</button></div></form></section></div></main><footer class="footer">Bingkaiin · Produk digital dari Apins Digital</footer></body></html>
